// Calculate extents of the bounding box
const T extent_x = bmax[0] - bmin[0];
const T extent_y = bmax[1] - bmin[1];
const T extent_z = bmax[2] - bmin[2];

// Calculate surface area of the bounding box
const T surface_area = T(2) * (extent_x * extent_y + extent_y * extent_z + extent_z * extent_x);

// Initialize variables to track minimum cost and axis
T min_cost = std::numeric_limits<T>::max();
int best_axis = -1;
T best_cut_pos = T(0);

// Number of bins (assuming BinBuffer has a method to get bin count)
const int num_bins = bins->GetBinCount();

// Iterate over each axis (x, y, z)
for (int axis = 0; axis < 3; ++axis) {
    // Skip axis with zero extent
    if ((axis == 0 && extent_x <= std::numeric_limits<T>::epsilon()) ||
        (axis == 1 && extent_y <= std::numeric_limits<T>::epsilon()) ||
        (axis == 2 && extent_z <= std::numeric_limits<T>::epsilon())) {
        continue;
    }

    // Initialize left and right bounding boxes and primitive counts
    T left_areas[num_bins];
    T right_areas[num_bins];
    int left_counts[num_bins];
    int right_counts[num_bins];

    // Calculate left and right areas and counts for each bin
    nanort::real3<T> left_bmin = bmin;
    nanort::real3<T> left_bmax = bmax;
    nanort::real3<T> right_bmin = bmin;
    nanort::real3<T> right_bmax = bmax;

    // Initialize left bounding box
    left_bmax[axis] = bmin[axis];

    // Initialize right bounding box
    right_bmin[axis] = bmax[axis];

    // Calculate left and right areas and counts
    for (int i = 0; i < num_bins; ++i) {
        // Update left bounding box max extent
        left_bmax[axis] = bmin[axis] + (bmax[axis] - bmin[axis]) * (i + 1) / num_bins;

        // Calculate left surface area
        T left_extent_x = left_bmax[0] - left_bmin[0];
        T left_extent_y = left_bmax[1] - left_bmin[1];
        T left_extent_z = left_bmax[2] - left_bmin[2];
        left_areas[i] = T(2) * (left_extent_x * left_extent_y + left_extent_y * left_extent_z + left_extent_z * left_extent_x);

        // Update right bounding box min extent
        right_bmin[axis] = bmin[axis] + (bmax[axis] - bmin[axis]) * i / num_bins;

        // Calculate right surface area
        T right_extent_x = right_bmax[0] - right_bmin[0];
        T right_extent_y = right_bmax[1] - right_bmin[1];
        T right_extent_z = right_bmax[2] - right_bmin[2];
        right_areas[i] = T(2) * (right_extent_x * right_extent_y + right_extent_y * right_extent_z + right_extent_z * right_extent_x);

        // Get primitive counts for left and right bins
        left_counts[i] = bins->GetLeftCount(axis, i);
        right_counts[i] = bins->GetTotalCount() - left_counts[i];
    }

    // Evaluate SAH cost for each bin split
    for (int i = 0; i < num_bins - 1; ++i) {
        // Skip if no primitives on either side
        if (left_counts[i] == 0 || right_counts[i] == 0) {
            continue;
        }

        // Calculate SAH cost
        T cost = T(2) * surface_area +  // Cost of traversing the node
                 (left_areas[i] * left_counts[i] + right_areas[i] * right_counts[i]) / surface_area;

        // Update minimum cost and best split
        if (cost < min_cost) {
            min_cost = cost;
            best_axis = axis;
            best_cut_pos = bmin[axis] + (bmax[axis] - bmin[axis]) * (i + 1) / num_bins;
        }
    }
}

// Check if a valid split was found
if (best_axis == -1) {
    return false;
}

// Set output parameters
cut_pos[0] = (best_axis == 0) ? best_cut_pos : bmin[0];
cut_pos[1] = (best_axis == 1) ? best_cut_pos : bmin[1];
cut_pos[2] = (best_axis == 2) ? best_cut_pos : bmin[2];
*minCostAxis = best_axis;

return true;

